const body = items[0].json.body || items[0].json;
const data = body.data || {};

const status = data.status || 'updated';
let emailSubject = `Pawlse Adoption Application Update for ${data.pet_name}`;
let emailBody = `Dear ${data.applicant_name},\n\nYour adoption application for ${data.pet_name} has been updated to: ${status.toUpperCase()}.`;

if (status === 'approved') {
  emailSubject = `Congratulations! Your Adoption Application for ${data.pet_name} is Approved!`;
  emailBody += `\n\nPlease proceed to your dashboard or shelter to complete the adoption handover.`;
} else if (status === 'scheduled') {
  emailSubject = `Pawlse: Shelter Interview Scheduled for ${data.pet_name}`;
  emailBody += `\n\nYour shelter visit and interview have been scheduled.`;
} else if (status === 'rejected') {
  emailSubject = `Pawlse: Update on your Adoption Application for ${data.pet_name}`;
  if (data.rejection_reason) {
    emailBody += `\n\nReason: ${data.rejection_reason}`;
  }
}

emailBody += `\n\nWarm regards,\nThe Pawlse Adoption Team`;

return [{
  json: {
    eventId: body.event_id,
    applicantName: data.applicant_name,
    applicantEmail: data.applicant_email,
    petName: data.pet_name,
    status: status,
    emailSubject: emailSubject,
    emailBody: emailBody,
    updatedAt: data.updated_at
  }
}];
